const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),eur=n=>new Intl.NumberFormat('it-IT',{style:'currency',currency:'EUR'}).format(n/100);let bookings=[],cfg,revision;
function message(s){$('#message').textContent=s}
async function api(path,method='GET',data){const r=await fetch('/api/'+path,{method,headers:{'Content-Type':'application/json'},cache:'no-store',...(data?{body:JSON.stringify(data)}:{})});let b;try{b=await r.json()}catch{throw Error('Servizio non disponibile. Controlla la configurazione Cloudflare.')}if(!r.ok){if(r.status===401){$('#loginForm').hidden=false;$('#dashboard').hidden=true;$('#logout').hidden=true}throw Error(b.error||'Operazione non riuscita')}return b}
async function load(){const [c,b]=await Promise.all([api('admin/config'),api('admin/bookings')]);cfg=c.config;revision=c.revision;bookings=b.bookings;$('#loginForm').hidden=true;$('#dashboard').hidden=false;$('#logout').hidden=false;$('#passFilter').innerHTML='<option value="all">Tutti i pass</option>'+[...new Map(bookings.map(b=>[b.pass_id,b.pass_name])).entries()].map(([id,name])=>`<option value="${esc(id)}">${esc(name)}</option>`).join('');editor();draw();if(b.truncated)message('Sono mostrate le prime 10.000 prenotazioni.');}
$('#loginForm').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{await api('login','POST',{password:new FormData(e.target).get('password')});e.target.reset();await load();message('Accesso eseguito.')}catch(e){message(e.message)}finally{button.disabled=false}};
$('#logout').onclick=async()=>{try{await api('logout','POST',{});location.reload()}catch(e){message(e.message)}};
$('#bookTab').onclick=()=>{$('#bookPanel').hidden=false;$('#configPanel').hidden=true;$('#bookTab').classList.add('active');$('#configTab').classList.remove('active')};$('#configTab').onclick=()=>{$('#bookPanel').hidden=true;$('#configPanel').hidden=false;$('#configTab').classList.add('active');$('#bookTab').classList.remove('active')};
function selected(){const q=$('#search').value.toLowerCase().trim(),status=$('#statusFilter').value,pass=$('#passFilter').value;return bookings.filter(b=>(status==='all'?b.status!=='deleted':b.status===status)&&(pass==='all'||b.pass_id===pass)&&[b.name,b.phone,b.id].join(' ').toLowerCase().includes(q))}
function workshops(b){try{return JSON.parse(b.workshops)}catch{return []}}
const statusName=s=>({confirmed:'Confermata',cancelled:'Annullata',deleted:'Nel cestino'}[s]||s);let pendingDelete=null;
function draw(){const active=bookings.filter(b=>b.status==='confirmed'),sum=key=>active.reduce((n,b)=>n+b[key],0),stageCounts=new Map();active.forEach(b=>workshops(b).forEach(s=>stageCounts.set(s.title,(stageCounts.get(s.title)||0)+b.qty)));const stats=[['Prenotazioni attive',active.length,'Liste confermate'],['Partecipanti',sum('qty'),'Persone attese'],['Buffet pizza',active.filter(b=>b.pass_id==='full').reduce((n,b)=>n+b.qty,0),'Coperti prenotati'],['Totale previsto',eur(sum('total_cents')),'Prenotazioni attive'],['Segnato pagato',eur(active.filter(b=>b.paid).reduce((n,b)=>n+b.total_cents,0)),'Importi registrati']];$('#stats').innerHTML=stats.map(([title,value,sub])=>`<article class="stat-card"><span>${esc(title)}</span><b>${esc(value)}</b><small>${esc(sub)}</small></article>`).join('');$('#stageCounts').innerHTML=[...stageCounts.entries()].map(([name,n])=>`<span class="stage-count">${esc(name)} <b>${n}</b></span>`).join('');$('#availability').textContent=cfg.open?'Prenotazioni aperte':'Prenotazioni chiuse';$('#availability').classList.toggle('is-open',cfg.open);const deleted=bookings.filter(b=>b.status==='deleted').length;$('#trashCount').textContent=deleted;const rows=selected();$('#resultCount').textContent=`${rows.length} prenotazioni · ${rows.reduce((n,b)=>n+b.qty,0)} persone`;$('#rows').innerHTML=rows.map(b=>`<tr class="booking-row ${b.status==='deleted'?'is-deleted':''}"><td class="guest-cell"><div class="guest-heading"><span class="avatar" aria-hidden="true">${esc(b.name.trim().split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase())}</span><div><b>${esc(b.name)}</b><a class="phone" href="tel:${esc(b.phone.replace(/[^+0-9]/g,''))}">${esc(b.phone)}</a></div></div><small class="booking-meta">#${esc(b.id.slice(0,8).toUpperCase())} · ${esc(new Date(b.created_at).toLocaleString('it-IT',{timeZone:'Europe/Rome',day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}))}</small>${b.notes?`<div class="booking-note">${esc(b.notes)}</div>`:''}</td><td class="pass-cell" data-label="Ingresso"><b>${esc(b.pass_name)}</b><div class="workshop-tags">${workshops(b).map(s=>`<span>${esc(s.title)}</span>`).join('')||'<span>Solo serata</span>'}</div></td><td data-label="Persone" class="quantity-cell"><strong>${b.qty}</strong></td><td data-label="Totale" class="amount-cell"><strong>${eur(b.total_cents)}</strong></td><td data-label="Pagato" class="toggle-cell"><label class="admin-toggle"><input type="checkbox" aria-label="Pagato ${esc(b.name)}" data-id="${b.id}" data-field="paid" ${b.paid?'checked':''} ${b.status==='deleted'?'disabled':''}><span aria-hidden="true"></span></label></td><td data-label="Arrivato" class="toggle-cell"><label class="admin-toggle"><input type="checkbox" aria-label="Arrivato ${esc(b.name)}" data-id="${b.id}" data-field="arrived" ${b.arrived?'checked':''} ${b.status==='deleted'?'disabled':''}><span aria-hidden="true"></span></label></td><td class="action-cell"><span class="status-badge ${esc(b.status)}">${statusName(b.status)}</span><div class="row-actions">${b.status==='deleted'?`<button data-action="restore" data-id="${b.id}">Recupera</button>`:`<button data-action="status" data-id="${b.id}">${b.status==='cancelled'?'Conferma di nuovo':'Annulla'}</button><button class="delete-button" data-action="delete" data-id="${b.id}">Elimina</button>`}</div></td></tr>`).join('');$('#empty').hidden=!!rows.length;$('#empty').textContent=$('#statusFilter').value==='deleted'?'Il cestino è vuoto.':'Nessuna prenotazione trovata. Modifica i filtri o aggiorna l’elenco.';document.querySelectorAll('[data-field]').forEach(el=>el.onchange=()=>change(el.dataset.id,el.dataset.field,el.checked,el));document.querySelectorAll('[data-action=status]').forEach(el=>el.onclick=()=>{const b=bookings.find(b=>b.id===el.dataset.id);change(b.id,'status',b.status==='cancelled'?'confirmed':'cancelled',el)});document.querySelectorAll('[data-action=delete]').forEach(el=>el.onclick=()=>{pendingDelete=el.dataset.id;const b=bookings.find(b=>b.id===pendingDelete);$('#deleteDescription').textContent=`${b.name} · ${b.qty} ${b.qty===1?'persona':'persone'} · ${eur(b.total_cents)}. La prenotazione verrà rimossa dagli elenchi e dai conteggi. Potrai recuperarla dal cestino.`;$('#deleteDialog').showModal()});document.querySelectorAll('[data-action=restore]').forEach(el=>el.onclick=()=>change(el.dataset.id,'status','cancelled',el));}
$('#deleteCancel').onclick=()=>{$('#deleteDialog').close();pendingDelete=null};$('#deleteConfirm').onclick=async()=>{if(!pendingDelete)return;const id=pendingDelete;$('#deleteConfirm').disabled=true;await change(id,'status','deleted',$('#deleteConfirm'));$('#deleteConfirm').disabled=false;$('#deleteDialog').close();pendingDelete=null};$('#trashButton').onclick=()=>{$('#statusFilter').value='deleted';draw()};
async function change(id,field,value,control){const b=bookings.find(b=>b.id===id),next={...b,[field]:value};control.disabled=true;try{await api('admin/bookings','PATCH',{id,status:next.status,paid:!!next.paid,arrived:!!next.arrived});const wasDeleted=b.status==='deleted';Object.assign(b,next);draw();message(field==='status'&&value==='deleted'?'Prenotazione spostata nel cestino.':field==='status'&&value==='cancelled'&&wasDeleted?'Prenotazione recuperata come annullata.':'Prenotazione aggiornata.')}catch(e){message(e.message);draw()}}
['#search','#statusFilter','#passFilter'].forEach(s=>$(s).oninput=draw);$('#refresh').onclick=async()=>{try{const b=await api('admin/bookings');bookings=b.bookings;draw();message('Elenco aggiornato.')}catch(e){message(e.message)}};
$('#csv').onclick=()=>{const cell=v=>'"'+String(v??'').replace(/^[\s]*[=+@-]/,"'").replace(/"/g,'""')+'"';const rows=[['Codice','Data','Nome','Telefono','Pass','Persone','Totale EUR','Stage','Note','Stato','Pagato','Arrivato'],...selected().map(b=>[b.id,b.created_at,b.name,b.phone,b.pass_name,b.qty,(b.total_cents/100).toFixed(2),workshops(b).map(s=>s.title).join(', '),b.notes,statusName(b.status),b.paid?'Sì':'No',b.arrived?'Sì':'No'])];const u=URL.createObjectURL(new Blob(['\ufeff'+rows.map(r=>r.map(cell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='park-latino-prenotazioni.csv';a.click();URL.revokeObjectURL(u)};
function editor(){$('#openBookings').checked=cfg.open;$('#configEditor').innerHTML='<div class="admin-card"><h3>Stage e programma</h3>'+cfg.stages.map((s,i)=>`<div class="stage-editor"><div class="two"><label>Nome attività<input data-stage="${i}" data-key="title" value="${esc(s.title)}" maxlength="200"></label><label>Orario<input data-stage="${i}" data-key="time" value="${esc(s.time)}" maxlength="80"></label></div><label>Insegnanti e scuola<input data-stage="${i}" data-key="teacher" value="${esc(s.teacher)}" maxlength="200"></label><label>Tipo<select data-stage="${i}" data-key="type">${['WORKSHOP','FOOD & FRIENDS','SALSA & BACHATA'].map(t=>`<option ${t===s.type?'selected':''}>${t}</option>`).join('')}</select></label><button class="text-button" data-remove="${i}">Rimuovi dal programma</button></div>`).join('')+'</div><div class="admin-card"><h3>Pass e prezzi</h3>'+cfg.passes.map((p,i)=>`<div class="stage-editor"><div class="two"><label>Nome pass<input data-pass="${i}" data-key="name" value="${esc(p.name)}" maxlength="80"></label><label>Prezzo €<input type="number" min="0" max="1000" step="0.01" data-pass="${i}" data-key="price" value="${p.price}"></label></div><label>Descrizione<input data-pass="${i}" data-key="desc" value="${esc(p.desc)}" maxlength="500"></label><label>Inclusioni (una per riga)<textarea data-pass="${i}" data-key="items">${esc(p.items.join('\n'))}</textarea></label><span class="muted">Stage selezionabili per questo pass</span>${cfg.stages.filter(s=>s.type==='WORKSHOP').map(s=>`<label class="check"><input type="checkbox" data-stage-pass="${i}" value="${esc(s.id)}" ${p.stages.includes(s.id)?'checked':''}>${esc(s.title)}</label>`).join('')}</div>`).join('')+'</div>';document.querySelectorAll('[data-stage],[data-pass],[data-stage-pass]').forEach(el=>el.onchange=()=>{if(el.dataset.stage!==undefined)cfg.stages[el.dataset.stage][el.dataset.key]=el.value;else if(el.dataset.pass!==undefined)cfg.passes[el.dataset.pass][el.dataset.key]=el.dataset.key==='price'?Number(el.value):el.dataset.key==='items'?el.value.split('\n').map(x=>x.trim()).filter(Boolean):el.value;else{const p=cfg.passes[el.dataset.stagePass];p.stages=el.checked?[...p.stages,el.value]:p.stages.filter(id=>id!==el.value)}});document.querySelectorAll('[data-remove]').forEach(el=>el.onclick=()=>{const i=Number(el.dataset.remove),id=cfg.stages[i].id;cfg.stages.splice(i,1);cfg.passes.forEach(p=>p.stages=p.stages.filter(x=>x!==id));editor()})}
$('#openBookings').onchange=e=>cfg.open=e.target.checked;$('#addStage').onclick=()=>{cfg.stages.push({id:'stage-'+crypto.randomUUID(),title:'Nuovo stage',time:'Da definire',teacher:'Da annunciare',type:'WORKSHOP'});editor()};$('#saveConfig').onclick=async()=>{const button=$('#saveConfig');button.disabled=true;try{const c=await api('admin/config','PUT',{config:cfg,revision});cfg=c.config;revision=c.revision;editor();message('Programma e prezzi salvati per tutti i visitatori.')}catch(e){message(e.message)}finally{button.disabled=false}};
api('admin/session').then(load).catch(e=>{if(!e.message.includes('Accedi'))message(e.message)});

